DROP TABLE IF EXISTS `expedientes_expediente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expedientes_expediente` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `numero` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `motivo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `puntos` decimal(10,2) NOT NULL,
  `estado` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `plazo_inicio_at` datetime(6) DEFAULT NULL,
  `plazo_limite_at` datetime(6) DEFAULT NULL,
  `descargo_presentado` tinyint(1) NOT NULL,
  `descargo_tipo` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descargo_causal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descargo_archivo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descargo_texto` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `descargo_presentado_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `socio_id` bigint NOT NULL,
  `calendario_version_id` bigint DEFAULT NULL,
  `urgencia` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `concepto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clasificacion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'GENERAL',
  `titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero` (`numero`),
  KEY `expedientes_expediente_socio_id_fk` (`socio_id`),
  KEY `expedientes_expedien_calendario_version_i_a4db4414_fk_expedient` (`calendario_version_id`),
  KEY `expedientes_expediente_urgencia_ba0743cb` (`urgencia`),
  KEY `expedientes_expediente_concepto_e7bcaf72` (`concepto`),
  KEY `expedientes_expediente_clasificacion_448173ea` (`clasificacion`),
  CONSTRAINT `expedientes_expedien_calendario_version_i_a4db4414_fk_expedient` FOREIGN KEY (`calendario_version_id`) REFERENCES `expedientes_calendario_version` (`id`),
  CONSTRAINT `expedientes_expediente_socio_id_fk` FOREIGN KEY (`socio_id`) REFERENCES `socios_socio` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=794 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
