DROP TABLE IF EXISTS `socio_domicilio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `socio_domicilio` (
  `compositeKey` int NOT NULL,
  `nroSocio` int NOT NULL,
  `direccion` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barrio` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ciudad` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `provincia` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `codTipoDomicilio` int NOT NULL,
  PRIMARY KEY (`compositeKey`),
  KEY `fk_dom_socio` (`nroSocio`),
  KEY `fk_dom_tipo` (`codTipoDomicilio`),
  CONSTRAINT `fk_dom_socio` FOREIGN KEY (`nroSocio`) REFERENCES `socio_lista` (`nroSocio`) ON DELETE CASCADE,
  CONSTRAINT `fk_dom_tipo` FOREIGN KEY (`codTipoDomicilio`) REFERENCES `socio_tipodomicilio` (`codTipoDomicilio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
