  CONSTRAINT `fk_historial_grupo` FOREIGN KEY (`idGrupo`) REFERENCES `grupo_lista` (`nroGrupo`),
  CONSTRAINT `fk_historial_motivo` FOREIGN KEY (`socio_motivoCambioEstado`) REFERENCES `socio_motivoCambioEstado` (`idMotivoCambio`),
