DROP TABLE IF EXISTS `socio_medio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `socio_medio` (
  `compositeKey` int NOT NULL,
  `nroSocio` int NOT NULL,
  `codMedio` int NOT NULL,
  `descripcion` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`compositeKey`),
  KEY `fk_medio_socio` (`nroSocio`),
