  CONSTRAINT `fk_medio_tipo` FOREIGN KEY (`codMedio`) REFERENCES `socio_tipomedio` (`codMedio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
