  CONSTRAINT `fk_tr_deleted_by` FOREIGN KEY (`deleted_by_id`) REFERENCES `auth_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tr_updated_by` FOREIGN KEY (`updated_by_id`) REFERENCES `auth_user` (`id`) ON DELETE SET NULL
